const SEQ=(typeof PD_SEQ==='object'&&PD_SEQ)||{};
function hasRealSeq(g){return !!SEQ[g]}
// Proteine aduse de utilizator din UniProt: rămân în telefon și merg apoi și fără internet
var PD_EXT={}; try{PD_EXT=JSON.parse(localStorage.getItem('pd_ext')||'{}')||{}}catch(e){PD_EXT={}}
function extReg(k,o){T[k]=[o.n,o.id]; D[k]=o.d||''; SEQ[k]=o.seq}
Object.keys(PD_EXT).forEach(k=>{const o=PD_EXT[k]; if(o&&o.seq&&o.id&&!T[k]) extReg(k,o); else if(!o||!o.seq) delete PD_EXT[k]});
function extSave(){try{localStorage.setItem('pd_ext',JSON.stringify(PD_EXT));return true}catch(e){return false}}
