/* ================== LISTA DE REDARE (ce proteine se cântă) ================== */
function planText(plan){
  if(!plan||!plan.length) return '';
  const part=plan.filter(p=>!p.rep).map(p=>'<b style="color:'+(p.inh?'#f9a8d4':'#6ee7b7')+'">'+(p.inh?'↓':'↑')+' '+p.gene+'</b> '+((p.from===1&&p.to>=p.total)?p.total+' aa':p.from+'–'+p.to+' / '+p.total+' aa'));
  return L('Se cântă, în ordine: ','Played, in order: ')+part.join(' · ')+(plan.some(p=>p.rep)?L(' (apoi se repetă)',' (then repeats)'):'');
}
function curGenes(){return S.lastGenes&&S.posKey===S.lastGenes.join(',')?S.lastGenes:(S.stack&&S.stack.genes)}
