function potdGene(){
  const om=new Set(); PRESETS.forEach(p=>{if((p.dom||'om')==='om') p.g.forEach(g=>om.add(g))});
  const ks=[...om].filter(g=>T[g]&&SEQ[g]&&!PD_EXT[g]&&D[g]&&SEQ[g].length<=450&&!INHIB_DEF.has(g)).sort(); if(!ks.length) return null;
  const d=new Date(), day=Math.floor(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate())/864e5); return ks[day%ks.length];
}
